target.css:
:root {
  --ink: #20243a;
  --muted: #6e7186;
  --paper: #ffffff;
  --line: #dedff0;
  --violet: #6658cf;
  --violet-pale: #f0efff;
  --mint: #dff5e9;
  --mint-ink: #247451;
  --amber: #fff0d5;
  --amber-ink: #a65b12;
  --rose: #fff1f3;
  --rose-ink: #c14f63;
}

* {
  box-sizing: border-box;
}

.repair-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.identity {
  display: flex;
  align-items: center;
  gap: 9px;
}

.mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  color: var(--paper);
  background: var(--violet);
  border-radius: 9px;
  font-size: 21px;
  font-weight: 700;
  line-height: 1;
}

.card-header h1,
.card-header p,
.device-copy h2,
.device-copy p,
.diagnosis-copy h3,
.diagnosis-copy p,
.tech p {
  margin: 0;
}

.card-header h1 {
  font-size: 15px;
  font-weight: 750;
  line-height: 1.1;
}

.card-header p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1;
}

.job-status {
  padding: 5px 8px;
  color: var(--mint-ink);
  background: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .7px;
}

.device-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.device-glyph {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  color: var(--violet);
  background: var(--violet-pale);
  border-radius: 11px;
  font-size: 22px;
}

.device-copy {
  min-width: 0;
  flex: 1;
}

.device-copy h2 {
  font-size: 15px;
  font-weight: 750;
  line-height: 1.2;
}

.device-copy p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.2;
}

.priority {
  padding: 5px 7px;
  color: var(--amber-ink);
  background: var(--amber);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 16px;
  background: var(--violet-pale);
  border-radius: 11px;
}

.metric {
  padding: 9px 12px 10px;
}

.metric + .metric {
  border-left: 1px solid var(--line);
}

.metric span,
.metric strong {
  display: block;
}

.metric span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .3px;
  text-transform: uppercase;
}

.metric strong {
  margin-top: 3px;
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
}

.diagnosis {
  display: grid;
  grid-template-columns: 25px 1fr;
  gap: 9px;
  align-items: start;
  margin: 12px 16px;
  padding: 9px 10px;
  background: var(--rose);
  border: 1px solid var(--rose-ink);
  border-radius: 10px;
}

.diagnosis-icon {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  color: var(--paper);
  background: var(--rose-ink);
  border-radius: 50%;
  font-size: 14px;
  font-weight: 800;
}

.diagnosis-copy h3 {
  font-size: 12px;
  font-weight: 800;
  line-height: 1.25;
}

.diagnosis-copy p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.3;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.tech,
.actions {
  display: flex;
  align-items: center;
}

.tech {
  gap: 7px;
}

.tech-badge {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  color: var(--violet);
  background: var(--violet-pale);
  border-radius: 50%;
  font-size: 10px;
  font-weight: 800;
}

.tech p {
  color: var(--muted);
  font-size: 11px;
}

.tech strong {
  color: var(--ink);
  font-weight: 800;
}

.actions {
  gap: 7px;
}

button {
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

.action-secondary {
  color: var(--ink);
  background: var(--paper);
}

.action-primary {
  color: var(--paper);
  background: var(--violet);
  border-color: var(--violet);
}

